import gurobipy as gp
from gurobipy import GRB
records = [rec for rec in LEGACY_RECORDS if rec['source'] == '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Others_example/Others1/42.csv']
if len(records) != 24:
    raise ValueError('Expected 24 records for 24 time periods, got {}'.format(len(records)))
periods = [str(i + 1) for i in range(24)]
r = {}
for (i, rec) in enumerate(records):
    shift = str(int(rec['values']['Shift']))
    if shift != periods[i]:
        raise ValueError(f'Shift mismatch at index {i}: got {shift}, expected {periods[i]}')
    try:
        r[periods[i]] = int(rec['values']['Number Required'])
    except Exception as e:
        raise ValueError(f"Invalid Number Required at shift {shift}: {rec['values']['Number Required']}") from e
m = gp.Model('bus_shift')
x_vars = m.addVars(periods, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((x_vars[t] for t in periods)), GRB.MINIMIZE)
for (idx, s) in enumerate(periods):
    indices = [(idx - k) % 24 for k in range(4)]
    m.addConstr(gp.quicksum((x_vars[periods[j]] for j in indices)) >= r[s], name=f'demand_{s}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')